al_close_materials","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_close_theory_lines","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_count_adjustment_postings","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_count_postings","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_other_issues","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_period_closes","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_period_lines","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_periods","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_requisition_lines","oldArgs":["native-facet-warehouse-inbound","native-facet-warehouse-outbound"],"newArgs":["native-facet-finance-columns","native-facet-warehouse-inbound","native-facet-warehouse-outbound"],"oldArgsHex":"6e61746976652d66616365742d77617265686f7573652d696e626f756e64006e61746976652d66616365742d77617265686f7573652d6f7574626f756e6400"},{"table":"workshop_material_requisition_postings","oldArgs":[],"newArgs":["native-facet-finance-columns"],"oldArgsHex":null},{"table":"workshop_material_requisitions","oldArgs":["native-facet-warehouse-inbound","native-facet-warehouse-outbound"],"newArgs":["native-facet-finance-columns","native-facet-warehouse-inbound","native-facet-warehouse-outbound"],"oldArgsHex":"6e61746976652d66616365742d77617265686f7573652d696e626f756e64006e61746976652d66616365742d77617265686f7573652d6f7574626f756e6400"}]$source_map$::jsonb;
BEGIN
 FOR relation IN SELECT value FROM jsonb_array_elements(expected_operations) LOOP
  SELECT string_agg(quote_literal(value),',' ORDER BY ordinality) INTO arguments
  FROM jsonb_array_elements_text(relation->'newArgs') WITH ORDINALITY;
  FOR event IN SELECT * FROM (VALUES
    ('insert','INSERT',4,'summary_new_rows',NULL::text,' REFERENCING NEW TABLE AS summary_new_rows'),
    ('update','UPDATE',16,'summary_new_rows',NULL::text,' REFERENCING NEW TABLE AS summary_new_rows'),
    ('delete','DELETE',8,NULL::text,'summary_old_rows',' REFERENCING OLD TABLE AS summary_old_rows'),
    ('truncate','TRUNCATE',32,NULL::text,NULL::text,''))
    AS events(suffix,operation,kind,new_rows,old_rows,transition) LOOP
   trigger_name:='trg_native_complete_marker_'||event.suffix;
   SELECT t.tgargs,t.tgtype,t.tgnewtable,t.tgoldtable,t.tgenabled,t.tgfoid INTO existing
   FROM pg_trigger t WHERE t.tgrelid=format('public.%I',relation->>'table')::regclass
     AND t.tgname=trigger_name AND NOT t.tgisinternal;
   IF relation->>'oldArgsHex' IS NULL THEN
    IF FOUND THEN RAISE EXCEPTION 'New source % unexpectedly already has %; preserve and review its arguments',relation->>'table',trigger_name;END IF;
   ELSE
    IF NOT FOUND OR encode(existing.tgargs,'hex') IS DISTINCT FROM relation->>'oldArgsHex'
      OR existing.tgtype<>event.kind OR existing.tgenabled<>'O'
      OR existing.tgnewtable IS DISTINCT FROM event.new_rows
      OR existing.tgoldtable IS DISTINCT FROM event.old_rows
      OR existing.tgfoid<>'public.fn_mark_summary_read_domain()'::regprocedure THEN
      RAISE EXCEPTION 'Original V1101 source %/% differs; do not discard another owner argument',relation->>'table',trigger_name;
    END IF;
    EXECUTE format('DROP TRIGGER %I ON public.%I',trigger_name,relation->>'table');
   END IF;
   EXECUTE format('CREATE TRIGGER %I AFTER %s ON public.%I%s FOR EACH STATEMENT EXECUTE FUNCTION public.fn_mark_summary_read_domain(%s)',
     trigger_name,event.operation,relation->>'table',event.transition,arguments);
  END LOOP;
 END LOOP;
END $native_sources$;

-- Retire every token issued before this dependency-definition cutover, even
-- if a previously untracked source changed before these triggers were installed.
DO $retire_old_snapshots$
DECLARE changed integer;
BEGIN
 UPDATE public.summary_read_domains SET epoch=gen_random_uuid()
 WHERE domain IN ('native-facet-arrival-exceptions','native-facet-arrival-expectations','native-facet-finance-columns');
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>3 THEN RAISE EXCEPTION 'The three original candidate domains must already exist';END IF;
END $retire_old_snapshots$;
